const fail = (m) => { throw new Fail(m) }

const NAME = /[A-Za-z0-9_-]/
const isWs = (c) => c === ' ' || c === '\t'
const newTable = () => ({ t: 'table', m: new Map(), hdr: false })

function parseLine(s, ctx) {
  let i = 0
  const eol = () => i >= s.length || s[i] === '#' || s[i] === ';'
  const ws = () => { while (i < s.length && isWs(s[i])) i++ }

  function str() {
    const q = s[i++]
    let out = ''
    if (q === "'") {
      const e = s.indexOf("'", i)
      if (e < 0) fail('unterminated string')
      out = s.slice(i, e); i = e + 1
      return out
    }
    for (;;) {
      if (i >= s.length) fail('unterminated string')
      const c = s[i++]
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      if (i >= s.length) fail('unterminated string')
      const e = s[i++]
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (e in map) out += map[e]
      else if (e === 'u') {
        const h = s.slice(i, i + 4)
        if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16)); i += 4
      } else fail('invalid escape \\' + e)
    }
  }

  function name() {
    if (s[i] === '"' || s[i] === "'") return str()
    const st = i
    while (i < s.length && NAME.test(s[i])) i++
    if (i === st) fail('expected a name')
    return s.slice(st, i)
  }

  function dotted() {
    const parts = [name()]
    for (;;) {
      const save = i
      ws()
      if (s[i] === '.') { i++; ws(); parts.push(name()) } else { i = save; return parts }
    }
  }

  const INT = /^[+-]?\d+(_\d+)*$/
  const FLT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

  function value(prefix) {
    ws()
    if (eol() || s[i] === ',' || s[i] === ']' || s[i] === '}') fail('expected a value')
    const c = s[i]
    if (c === '"' || c === "'") return { t: 'string', v: str() }
    if (c === '[') return array(prefix)
    if (c === '{') return inline(prefix)
    const st = i
    while (i < s.length && !isWs(s[i]) && !',]};'.includes(s[i])) i++
    const w = s.slice(st, i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    if (INT.test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
    if (FLT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }

  function array(prefix) {
    i++
    const items = []
    const node = { t: 'array', items, aot: false }
    ws()
    for (;;) {
      ws()
      if (i >= s.length || s[i] === '#' || s[i] === ';') fail('unterminated array')
      if (s[i] === ']') { i++; return node }
      items.push(value(prefix + '[' + items.length + ']'))
      ws()
      if (s[i] === ',') { i++; continue }
      if (s[i] === ']') { i++; return node }
      if (eol()) fail('unterminated array')
      fail('trailing text after a value')
    }
  }

