      path = path ? path + '.' + keys[k] : keys[k]
      let nx = cur.m.get(keys[k])
      if (!nx) { nx = newTable(); cur.m.set(keys[k], nx) }
      if (nx.t === 'array' && nx.aot) nx = nx.items[nx.items.length - 1]
      else if (nx.t !== 'table') fail(path + ' is not a table')
      cur = nx
    }
