function json(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  switch (n.t) {
    case 'table': {
      const ks = sortedKeys(n.m)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + json(n.m.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
