    case 'array':
      if (!n.items.length) return '[]'
      return '[\n' + n.items.map((x) => pad + json(x, ind + 1)).join(',\n') + '\n' + end + ']'
    case 'integer': return n.v.toString()
    default: return JSON.stringify(n.v)
  }
}

function keys(n, path, out) {
  if (n.t === 'table') {
    for (const k of sortedKeys(n.m)) {
      const p = path ? path + '.' + k : k
      const c = n.m.get(k)
